const samples = await IO.loadMNIST();
const side = 28;
const pixels = side * side;
const K = 10;
const eigenK = 32;
const sigma = 0.25;
if (samples.length < K) throw new Error("At least 10 MNIST images are required");

// Four-neighbor pixel grid with undirected edges.
const graph = new Graph();
for (let i = 0; i < pixels; i++) graph.addVertex(i);
for (let row = 0; row < side; row++) {
    for (let col = 0; col < side; col++) {
        const i = row * side + col;
        if (col + 1 < side) {
            graph.addEdge(i, i + 1);
            graph.addEdge(i + 1, i);
        }
        if (row + 1 < side) {
            graph.addEdge(i, i + side);
            graph.addEdge(i + side, i);
        }
    }
}
// One shared graph: compare each pair of pixel positions across all images.
const laplacian = graph.laplacian((a, b) => {
    let squaredDifference = 0;
    for (const sample of samples) squaredDifference += (sample[a.id] - sample[b.id]) ** 2;
    return Math.exp(-squaredDifference / (samples.length * 2 * sigma ** 2));
});
const {eigenvectors} = laplacian.eigen({maxFirst: false, k: eigenK});
const basis = eigenvectors.map(vector => vector.toArray());

// Each image is represented by its coefficients in the low-energy basis.
const features = samples.map(sample => basis.map(vector => {
    let coefficient = 0;
    for (let i = 0; i < pixels; i++) coefficient += sample[i] * vector[i];
    return coefficient;
}));
const kmeans = Kmeans.new(features, K, {maxIterations: 20}).fit();
const means = Array.from({length: K}, () => new Float32Array(pixels));
const counts = new Array(K).fill(0);
for (let n = 0; n < samples.length; n++) {
    const cluster = kmeans.predictIndex(features[n]);
    counts[cluster]++;
    for (let i = 0; i < pixels; i++) means[cluster][i] += samples[n][i];
}
for (let cluster = 0; cluster < K; cluster++) {
    if (counts[cluster] === 0) {
        console.warn(`Cluster ${cluster} is empty`);
        continue;
    }
    for (let i = 0; i < pixels; i++) means[cluster][i] /= counts[cluster];
}
IO.paintMNIST(means, 5);
